/**
 * E2E: CC hook-event registration completeness (#3327)
 *
 * Two invariants, both of which were violated at the time this file was added:
 *
 *   1. DirectoryAdded (CC 2.1.219) and MessageDisplay (CC 2.1.152) are
 *      registered in hooks.json AND resolvable through the entries map.
 *      A key in only one of the two places is a silently-dead hook — the
 *      #959 defect class, the single most repeated bug in this codebase.
 *
 *   2. tests/hooks/test-hook-structure.sh's VALID_EVENTS allowlist is a
 *      SUPERSET of hooks.json's event keys. That list is a hand-maintained
 *      literal in a shell script with no automated coupling to hooks.json,
 *      so it hard-fails the moment a new event is registered. This test
 *      derives the coupling instead of restating it, so the trap can only
 *      be sprung once.
 */

import { describe, it, expect, beforeAll } from 'vitest';
import fs from 'node:fs';
import path from 'node:path';

import { hooks as lifecycleHooks } from '../../entries/lifecycle.js';
import { hooks as notificationHooks } from '../../entries/notification.js';

interface Hook {
  type: string;
  command?: string;
  args?: string[];
  async?: boolean;
  timeout?: number;
}
interface HookGroup {
  matcher?: string;
  hooks: Hook[];
}
interface HooksConfig {
  hooks: Record<string, HookGroup[]>;
}

const HOOKS_ROOT = path.resolve(__dirname, '..', '..', '..');
const REPO_ROOT = path.resolve(HOOKS_ROOT, '..', '..');
const STRUCTURE_TEST = path.join(REPO_ROOT, 'tests', 'hooks', 'test-hook-structure.sh');

/** Handler paths a hooks.json event dispatches, read from the args[] exec form. */
function handlersFor(config: HooksConfig, event: string): string[] {
  const groups = config.hooks[event] ?? [];
  return groups
    .flatMap((g) => g.hooks ?? [])
    .map((h) => {
      const args = h.args ?? [];
      return args[args.length - 1] ?? '';
    })
    .filter((a) => a.length > 0 && !a.endsWith('.mjs'));
}

describe('CC hook-event registration (#3327)', () => {
  let config: HooksConfig;

  beforeAll(() => {
    config = JSON.parse(fs.readFileSync(path.join(HOOKS_ROOT, 'hooks.json'), 'utf-8'));
  });

  describe('DirectoryAdded (CC 2.1.219)', () => {
    it('is registered in hooks.json', () => {
      expect(config.hooks.DirectoryAdded, 'DirectoryAdded missing from hooks.json').toBeDefined();
      expect(config.hooks.DirectoryAdded.length).toBeGreaterThan(0);
    });

    it('every registered handler resolves in the entries map (#959 pair)', () => {
      const registry = { ...lifecycleHooks, ...notificationHooks };
      const handlers = handlersFor(config, 'DirectoryAdded');
      expect(handlers.length, 'no resolvable handler registered').toBeGreaterThan(0);
      for (const h of handlers) {
        expect(registry[h], `${h} in hooks.json but not in the entries map`).toBeTypeOf('function');
      }
    });

    it('is a member of the HookEvent union in types.ts', () => {
      const types = fs.readFileSync(path.join(HOOKS_ROOT, 'src', 'types.ts'), 'utf-8');
      expect(types).toMatch(/^\s*\|\s*'DirectoryAdded';?$/m);
    });
  });

  describe('MessageDisplay (CC 2.1.152)', () => {
    it('is registered in hooks.json', () => {
      expect(config.hooks.MessageDisplay, 'MessageDisplay missing from hooks.json').toBeDefined();
      expect(config.hooks.MessageDisplay.length).toBeGreaterThan(0);
    });

    it('every registered handler resolves in the entries map (#959 pair)', () => {
      const registry = { ...lifecycleHooks, ...notificationHooks };
      const handlers = handlersFor(config, 'MessageDisplay');
      expect(handlers.length, 'no resolvable handler registered').toBeGreaterThan(0);
      for (const h of handlers) {
        expect(registry[h], `${h} in hooks.json but not in the entries map`).toBeTypeOf('function');
      }
    });
  });

  describe('test-hook-structure.sh VALID_EVENTS coupling', () => {
    it('allowlists every event key present in hooks.json', () => {
      const script = fs.readFileSync(STRUCTURE_TEST, 'utf-8');
      const match = script.match(/^VALID_EVENTS="([^"]*)"$/m);
      expect(match, 'VALID_EVENTS assignment not found in test-hook-structure.sh').not.toBeNull();

      const allowed = new Set((match?.[1] ?? '').split(/\s+/).filter(Boolean));
      const missing = Object.keys(config.hooks).filter((e) => !allowed.has(e));
      expect(missing, `VALID_EVENTS is missing: ${missing.join(', ')}`).toEqual([]);
    });
  });
});
